static inline fixed_bytes_20 fixed_bytes_20_zero(void) {
  fixed_bytes_20 result = {{0}};
  return result;
}


static inline bool eq_fixed_bytes_20(const fixed_bytes_20 op1, const fixed_bytes_20 op2) {
  if (memcmp(op1.bytes, op2.bytes, 8) != 0) {
    return false;
  }
  if (memcmp(op1.bytes + 8, op2.bytes + 8, 8) != 0) {
    return false;
  }
  return memcmp(op1.bytes + 16, op2.bytes + 16, 4) == 0;
}


#ifndef SAIL_U256_DEFINED
#define SAIL_U256_DEFINED
typedef struct { uint64_t limbs[4]; } u256;
#endif

static inline u256 u256_from_fixed_bytes_20(const fixed_bytes_20 value) {
  u256 result = {{0}};
  for (size_t i = 0; i < 20; ++i) {
    result.limbs[i >> 3] |= ((uint64_t)value.bytes[i]) << ((i & 7) * 8);
  }
  return result;
}

static inline fixed_bytes_20 fixed_bytes_20_from_u256(const u256 value) {
  fixed_bytes_20 result = {0};
  for (size_t i = 0; i < 20; ++i) {
    result.bytes[i] = (uint8_t)(value.limbs[i >> 3] >> ((i & 7) * 8));
  }
  return result;
}


static inline fixed_bytes_20 vector_init_fixed_bytes_20(const sail_int length_arg, const uint64_t elem) {
  (void)length_arg;
  fixed_bytes_20 result = {0};
  for (size_t i = 0; i < 20; ++i) {
    result.bytes[i] = (uint8_t)elem;
  }
  return result;
}

static inline fixed_bytes_20 undefined_vector_fixed_bytes_20(const sail_int length_arg, const uint64_t elem) {
  return vector_init_fixed_bytes_20(length_arg, elem);
}

static inline fixed_bytes_20 vector_update_fixed_bytes_20(fixed_bytes_20 value, const sail_int index, const uint64_t elem) {
  const uint64_t i = sail_int_get_ui(index);
  if (i < 20) {
    value.bytes[i] = (uint8_t)elem;
  }
  return value;
}

static inline uint64_t vector_access_fixed_bytes_20(const fixed_bytes_20 value, const sail_int index) {
  const uint64_t i = sail_int_get_ui(index);
  return i < 20 ? (uint64_t)value.bytes[i] : UINT64_C(0);
}

static inline void length_fixed_bytes_20(sail_int *result, const fixed_bytes_20 value) {
  (void)value;
  mpz_set_ui(*result, 20);
}

static inline fixed_bytes_20 internal_vector_init_fixed_bytes_20(const int64_t length_arg) {
  (void)length_arg;
  return fixed_bytes_20_zero();
}

static inline fixed_bytes_20 internal_vector_update_fixed_bytes_20(
    fixed_bytes_20 value, const int64_t index, const uint64_t elem) {
  if (index >= 0 && index < 20) {
    value.bytes[index] = (uint8_t)elem;
  }
  return value;
}

static inline uint64_t fast_vector_access_fixed_bytes_20(const fixed_bytes_20 value, const int64_t index) {
  return index >= 0 && index < 20 ? (uint64_t)value.bytes[index] : UINT64_C(0);
}

